import skarstrom as sk

sim = sk.Simulation.new()
sim.info.title = 'Vysyaraju 2024 - PSA exp1'
sim.info.description = ''
sim.info.author = 'Vysyaraju et al. (2024)'

# ---- fluid --------------------------------------------------------------------
sim.add_component('Nitrogen')
sim.add_component('Helium')
sim.fluid.adsorbed_heat_capacity_mode = 0
sim.fluid.heat_of_adsorption_convention = 0
sim.fluid.adsorbed_heat_capacity['Nitrogen'] = 29.1
sim.fluid.adsorbed_heat_capacity['Helium'] = 0.0

# ---- adsorbents -----------------------------------------------------------------
ads_zeolite5a = sim.add_adsorbent('Zeolite5A', solid_density=1183.6, heat_capacity=960.0, thermal_conductivity=0.15, particle_void_fraction=0.33)
ads_zeolite5a.set_isotherm('dual_site_langmuir_c', {
    'Nitrogen': {'m1': 3.072, 'b1': 1.576e-06, 'q1': 18090.0, 'm2': 0.646, 'b2': 9.195e-06, 'q2': 19360.0},
}, components=['Nitrogen'])
ads_zeolite5a.set_isotherm('inert', components=['Helium'])
ads_zeolite5a.set_rate_model('Nitrogen', 'ldf', 'constant', k=104.98161937977187)
ads_zeolite5a.set_rate_model('Helium', 'ldf', 'constant', k=0.5)
ads_zeolite5a.heat_of_adsorption['Nitrogen'] = 18700.0
ads_zeolite5a.heat_of_adsorption['Helium'] = 0.0

# ---- column ----------------------------------------------------------------------
sim.bed.set_shape('cylinder', diameter=0.034)
sim.bed.ambient_temperature = 298.0
sim.bed.set_thermal_equilibrium('lte')
sim.bed.set_particle_heat_transfer('constant', particle_htc=100.0)
sim.bed.bottom_void.enabled = False
sim.bed.bottom_void.volume = 0.0001
sim.bed.bottom_void.resistance_coefficient = 0.0
sim.bed.top_void.enabled = False
sim.bed.top_void.volume = 0.0001
sim.bed.top_void.resistance_coefficient = 0.0
sim.wall.set_material('ss316l', density=7800.0, heat_capacity=502.0, thermal_conductivity=16.0)
sim.wall.thickness = 0.0019999999999999983
sim.wall.set_boundary('zero_flux')

# ---- layers (feed end first) ------------------------------------------------------
layer_zeolite5a = sim.add_layer('Zeolite5A', composition={'Zeolite5A': 1.0}, momentum='kozeny_carman', length=0.305, cells=30, bed_void_fraction=0.35, particle_diameter=0.00206)
layer_zeolite5a.set_dispersion('ruthven', molecular_diffusion_coefficient=1.6e-05)
layer_zeolite5a.set_heat_dispersion('constant', heat_dispersion_coefficient=0.0)
layer_zeolite5a.set_internal_heat_transfer('constant', internal_htc=15.0)
layer_zeolite5a.set_external_heat_transfer('constant', external_htc=15.0)

# ---- initial conditions --------------------------------------------------------
sim.initial_conditions.pressure = 1404300.0
sim.initial_conditions.temperature = 298.0
sim.initial_conditions.wall_temperature = 298.0
sim.initial_conditions.velocity = 0.0
sim.initial_conditions.y['Nitrogen'] = 0.0
sim.initial_conditions.y['Helium'] = 1.0

# ---- cycle -------------------------------------------------------------------------
sim.cycle.number_of_cycles = 60
sim.cycle.step_time_mode = 0
pres = sim.add_step('PRES', time=30.0)
pres.bottom.set_streams('inlet', [
    sk.ValveStream('', pressure=1510000.0, cv=0.012, xt=0.53, y={'Nitrogen': 0.9, 'Helium': 0.1}, temperature=298.0),
])
pres.top.set_closed()
ads_2 = sim.add_step('ADS', time=15.0)
ads_2.bottom.set_streams('inlet', [
    sk.Stream('', flow=sk.velocity(0.005), y={'Nitrogen': 0.9, 'Helium': 0.1}, temperature=298.0),
])
ads_2.top.set_pressure('outlet', 1510000.0, y={'Nitrogen': 0.9, 'Helium': 0.1}, temperature=293.0)
ped = sim.add_step('PED', time=30.0)
ped.bottom.set_closed()
ped.top.set_streams('outlet', [
    sk.ValveStream('PE stream', pressure=700000.0, cv=0.2, xt=0.53, y={'Nitrogen': 0.0, 'Helium': 0.0}, temperature=293.0),
])
blo = sim.add_step('BLO', time=30.0)
blo.bottom.set_pressure('outlet', sk.exponential(100000.0), y={'Nitrogen': 0.9, 'Helium': 0.1}, temperature=293.0)
blo.top.set_closed()
per = sim.add_step('PER', time=30.0)
per.bottom.set_closed()
per.top.set_streams('inlet', [
    sk.Stream('PE stream', flow=sk.velocity(0.0), y={'Nitrogen': 0.9, 'Helium': 0.1}, temperature=298.0),
])
sim.connect(ped.top['PE stream'], per.top['PE stream'])

# ---- solver, cyclic steady state, energy balance --------------------------------------
sim.settings.init_step = 1e-10
sim.settings.min_step = 1e-15
sim.settings.max_step = 1.0
sim.settings.reltol = 1e-06
sim.settings.nonlin_conv_coef = 0.1
sim.settings.max_order = 5
sim.settings.max_nonlin_iters = 15
sim.settings.max_conv_fails = 200
sim.settings.max_err_test_fails = 40
sim.settings.max_num_steps = 100000
sim.settings.max_iters_per_step = 50000
sim.settings.advection_scheme = 0
sim.settings.max_cycles_to_keep = 10
sim.settings.max_log_points_per_step = 200
sim.settings.acceleration_method = 0
sim.css.method = 3
sim.css.min_cycles = 60
sim.css.molar_absolute_tolerance = 0.0001
sim.css.molar_relative_tolerance = 0.0001
sim.css.mass_balance_tolerance = 0.005
sim.energy_balance.energy_balance_mode = 0
sim.energy_balance.isothermal_use_initial_temperature = True
sim.energy_balance.isothermal_temperature = 298.15


if __name__ == "__main__":
    import sys

    result = sim.run(cycles=int(sys.argv[1]) if len(sys.argv) > 1 else None)
    print(result.status, f"after {result.cycles_run} cycles")
    for k in sim.kpis(cycle=-1):
        print(f"{k.component}: purity {k.purity:.4f}, recovery {k.recovery:.4f}")
